import {
  SpinalUserManager
} from "spinal-core-connectorjs";
var angular = require("angular");

angular
  .module("app.controllers")
  .controller("RightMenuCtrl", [
    "$scope",
    "$mdSidenav",
    "$location",
    "authService",
    "$mdDialog",
    "$templateCache",
    "config",
    function (
      $scope,
      $mdSidenav,
      $location,
      authService,
      $mdDialog,
      $templateCache,
      config
    ) {
      authService.wait_connect().then(() => {
        $scope.username = authService.get_user().username;
      });

      $scope.close = function () {
        $mdSidenav("right").close();
      };

      $scope.logOut = () => {
        $mdSidenav("right")
          .close()
          .then(function () {
            $mdDialog
              .show(
                $mdDialog
                  .confirm()
                  .ariaLabel("confirm menu")
                  .ok("Confirm")
                  .cancel("Cancel")
                  .title("Do you want to log out ?")
                  .targetEvent(event)
              )
              .then(
                function () {
                  $location.path("/login");
                },
                function () { }
              );
          });
      };
      $scope.GoToAdmin = function () {
        const win = window.open("/html/admin/", "_blank");
        win.focus();
        $mdSidenav("right")
          .close()
          .then(function () { });
      };
      $scope.GoToDrive = function () {
        const win = window.open("/html/drive/", "_blank");
        win.focus();
        $mdSidenav("right")
          .close()
          .then(function () { });
      };
      $scope.GoToUserManager = function () {
        const win = window.open("/html/user_role_manager/", "_blank");
        win.focus();
        $mdSidenav("right")
          .close()
          .then(function () { });
      };

      $scope.modifyPassword = function (event) {
        $mdSidenav("right")
          .close()
          .then(function () {
            let my_prompt = $mdDialog
              .confirm()
              .ariaLabel("confirm menu")
              .ok("Confirm")
              .cancel("Cancel")
              .title("Do you want to modify your password ?")
              .targetEvent(event);
            $mdDialog.show(my_prompt).then(
              function () {
                $mdDialog.show({
                  ariaLabel: "changePasswordModal",
                  template: $templateCache.get("changePasswordModal.html"),
                  parent: angular.element(document.body),
                  clickOutsideToClose: true,
                  fullscreen: true,
                  controller: [
                    "$scope",
                    "authService",
                    "$mdToast",
                    "$q",
                    "$mdDialog",
                    'ngSpinalCore',
                    changePasswordModelCtrl
                  ]
                });
              },
              function () { }
            );
          });
      };
      $scope.menuList = [];
      if (config.mode === "admin") {
        $scope.menuList.push({
          name: "Open Drive",
          action: $scope.GoToDrive
        }, {
          name: "Open User Manager",
          action: $scope.GoToUserManager
        });
      } else {
        $scope.menuList.push({
          name: "Open Admin",
          action: $scope.GoToAdmin
        });
      }
      $scope.menuList.push({
        name: "Change Password",
        action: $scope.modifyPassword
      });
      $scope.menuList.push({
        name: "Log out",
        action: $scope.logOut
      });
    }
  ])
  .controller("navbarCtrl", [
    "$scope",
    "authService",
    "$location",
    "goldenLayoutService",
    "$mdSidenav",
    function ($scope, authService, $location, goldenLayoutService, $mdSidenav) {
      $scope.username = "";
      $scope.connected = false;

      authService.wait_connect().then(() => {
        $scope.username = authService.get_user().username;
        $scope.connected = true;
      });

      $scope.logout = () => {
        $location.path("/login");
      };
      $scope.clickUser = () => {
        $mdSidenav("right").open();
      };

      // get in SpinalDrive_Env
      $scope.layouts = [
        {
          id: "drag-folder-explorer",
          name: "Folder Explorer",
          cfg: {
            isClosable: true,
            title: "Folder Explorer",
            type: "component",
            width: 20,
            componentName: "SpinalHome",
            componentState: {
              template: "sideBar.html",
              module: "app.sidebar",
              controller: "sideBarCtrl"
            }
          }
        },

        {
          id: "drag-file-explorer",
          name: "File Explorer",
          cfg: {
            isClosable: true,
            title: "File Explorer",
            type: "component",
            componentName: "SpinalHome",
            componentState: {
              template: "FileExplorer.html",
              module: "app.FileExplorer",
              controller: "FileExplorerCtrl"
            }
          }
        },

        {
          id: "drag-inspector",
          name: "DB Inspector",
          cfg: {
            isClosable: true,
            title: "DB Inspector",
            type: "component",
            componentName: "SpinalHome",
            componentState: {
              template: "inspector.html",
              controller: "InspectorCtrl"
            }
          }
        }
      ];

      for (var i = 0; i < $scope.layouts.length; i++) {
        goldenLayoutService.registerPanel($scope.layouts[i]);
      }
    }
  ]);
var changePasswordModelCtrl = function (
  $scope,
  authService,
  $mdToast,
  $q,
  $mdDialog,
  ngSpinalCore
) {
  $scope.passwordInputType = "password";
  $scope.showPassword = function () {
    $scope.passwordInputType = "text";
  };
  $scope.hidePassword = function () {
    $scope.passwordInputType = "password";
  };

  $scope.cancel = function () {
    $mdDialog.cancel();
  };
  $scope.change_password = {
    currentPassword: "",
    password: "",
    confirm_password: ""
  };
  $scope.onError = function (err) {
    $mdToast.showSimple("Error : " + err);
  };

  $scope.changePasswordSubmit = (newpasswordForm, change_password) => {
    if (newpasswordForm.$valid) {
      let user = authService.get_user();
      ngSpinalCore
        .change_password(
          user.username,
          change_password.currentPassword,
          change_password.password
        )
        .then(function () {
          authService.save_user(user.username, change_password.password);
          $mdToast.showSimple("Password has been successfully modified.");
          $mdDialog.hide();
        }, $scope.onError);
      return;
    }
  };
};
